    public static int inTryInline(emon.Port.Cells wd, emon.Port.Cells gl, emon.Port.Cells lt, emon.Port.Cells fo, emon.Port.Cells et, emon.Port.Cells sc, emon.Port.Cells sq, emon.Port.Cells ii, int l, int s) {
        // Is the start of line l's first word an initial that the text layer put in the line: leading glyphs at least IN_MIN
        // tenths of the size of the glyphs after them? Three kinds, by where their baseline is (SPEC 10.9):
        //   * ON THE LINE'S BASELINE with lines above it that start after it: a DROP initial whose baseline is that of its last
        //     line (the print convention), so the lines are made of it. The highest of the lines above begins the paragraph, its cap
        //     top is the initial's, line N+1 starts back at the initial's start edge; the line's cell 15 is minus the code points
        //     that are the initial's;
        //   * ON THE LINE'S BASELINE with no line above beside it: a RAISED initial, line 2 at its start edge;
        //   * BELOW THE LINE'S BASELINE (the initial and the rest of its word share a line, the initial's baseline is that of a
        //     later line): a DROP initial in the first line's first word, lines 2..N start after it, line N+1 back at its start edge.
        // The line's box is made the box of its other glyphs. Records it and answers 1, else 0.
        int w0 = Evidence.lnGet(lt, l, Evidence.lhFirst());
        int wn = Evidence.lnGet(lt, l, Evidence.lhCount());
        int g0 = Evidence.wdGet(wd, w0, Evidence.wfGfirst());
        int gn = Evidence.wdGet(wd, w0, Evidence.wfGcount());
        int ts = Evidence.wdGet(wd, w0, Evidence.hdTstart());
        int tl = Evidence.wdGet(wd, w0, Evidence.hdTlen());
        int ngl = emon.Port.cellsLen(gl) / 32;
        if (wn < 2) {
            return 0;
        }
        if ((g0 < 0) || (gn < 1) || ((g0 + gn) > ngl)) {
            return 0;
        }
        if ((ts < 0) || (tl != gn)) {
            return 0;
        }
        int big = inCap(Evidence.glGet(gl, g0, Evidence.gfSize()));
        int ibase = inClamp(Evidence.glGet(gl, g0, Evidence.gfBy0()));
        int lineBase = 0;
        int r = 1;
        int g = 0;
        int body = 0;
        int ok = 1;
        if (big < 1) {
            return 0;
        }
        while ((r < gn) && ((inCap(Evidence.glGet(gl, g0 + r, Evidence.gfSize())) * 100) >= (big * 95))) {
            r += 1;
        }
        if (r > 3) {
            if (r < gn) {
                return 0;
            }
        }
        if (r > IN_MAXCP) {
            return 0;
        }
        if (r < gn) {
            body = inCap(Evidence.glGet(gl, g0 + r, Evidence.gfSize()));
        } else {
            body = inCap(Evidence.wdGet(wd, w0 + 1, Evidence.wfSize()));
        }
        if (body < 1) {
            return 0;
        }
        if ((big * 10) < (IN_MIN * body)) {
            return 0;
        }
        // The line's own baseline is that of the glyphs after the initial: the text layer gives a line the baseline of its
        // first glyph at its start, which is the initial's.
        if (r < gn) {
            lineBase = inClamp(Evidence.glGet(gl, g0 + r, Evidence.gfBy0()));
        } else {
            lineBase = inClamp(Evidence.wdGet(wd, w0 + 1, Evidence.hdBy0()));
        }
        g = 0;
        while (g < r) {
            if (Evidence.glGet(gl, g0 + g, Evidence.chCp()) != emon.Port.cellsAt(et, ts + g)) {
                ok = 0;
            }
            if ((inAbs(inClamp(Evidence.glGet(gl, g0 + g, Evidence.gfBy0())) - ibase) * IN_SLACK_DIV) > body) {
                ok = 0;
            }
            g += 1;
        }
        if (ok == 0) {
            return 0;
        }
        if (!inAlnum(emon.Port.cellsAt(et, ts))) {
            if ((tl < 2) || !inAlnum(emon.Port.cellsAt(et, ts + 1))) {
                return 0;
            }
        }
        if ((r == gn) && inFigure(et, ts, tl)) {
            return 0;
        }
        int y0 = 0;
        int y1 = 0;
        int ix0 = 0;
        int iy0 = 0;
        int ix1 = 0;
        int iy1 = 0;
        int have = 0;
        int k = 0;
        int above = 0;
        int cur = l;
        int m = 0;
        int p = 0;
        int ng = 0;
        int more = 1;
        g = 0;
        while (g < gn) {
            int gy0 = inClamp(Evidence.glGet(gl, g0 + g, Evidence.chY0()));
            int gy1 = inClamp(Evidence.glGet(gl, g0 + g, Evidence.chY1()));
            int gx0 = inClamp(Evidence.glGet(gl, g0 + g, Evidence.chX0()));
            int gx1 = inClamp(Evidence.glGet(gl, g0 + g, Evidence.chX1()));
            if (g < r) {
                if (g == 0) {
                    ix0 = gx0;
                    iy0 = gy0;
                    ix1 = gx1;
                    iy1 = gy1;
                } else {
                    ix0 = inLo(ix0, gx0);
                    iy0 = inLo(iy0, gy0);
                    ix1 = inHi(ix1, gx1);
                    iy1 = inHi(iy1, gy1);
                }
            } else {
                if (have == 0) {
                    y0 = gy0;
                    y1 = gy1;
                    have = 1;
                } else {
                    y0 = inLo(y0, gy0);
                    y1 = inHi(y1, gy1);
                }
            }
            g += 1;
        }
        k = 1;
        while (k < wn) {
            int wy0 = inClamp(Evidence.wdGet(wd, w0 + k, Evidence.hdY0()));
            int wy1 = inClamp(Evidence.wdGet(wd, w0 + k, Evidence.hdY1()));
            if (have == 0) {
                y0 = wy0;
                y1 = wy1;
                have = 1;
            } else {
                y0 = inLo(y0, wy0);
                y1 = inHi(y1, wy1);
            }
            k += 1;
        }
        if (have == 0) {
            return 0;
        }
        // The line's baseline is the body's from here on (the lines around it are placed by it): kept whether or not the
        // line proves to hold an initial, since it is the truer one.
        emon.Port.cellsSet(lt, (l * 16) + Evidence.lhBy0(), lineBase);
        int cs = inStart(lt, l, s);
        int ce = inEend(s, ix0, ix1);
        int font = Evidence.wdGet(wd, w0, Evidence.wfFont());
        int cp0 = inCp0(wd, et, w0);
        int ratio = inRatio(fo, font, cp0);
        int up = inUp(cp0, big);
        int captop = ibase - ((big * ratio) / 1000);
        if ((inAbs(ibase - lineBase) * IN_SLACK_DIV) <= body) {
            emon.Port.cellsDrop(sq, 0);
            while ((more == 1) && (emon.Port.cellsLen(sq) < IN_MAXLINES)) {
                m = inPrev(lt, sc, cur, s, ce - (body / IN_SLACK_DIV), ce + (body * 2), body);
                if (m < 0) {
                    more = 0;
                } else if ((inAbs(inLsize(wd, lt, m) - body) * 10) > (body * 2)) {
                    more = 0;
                } else {
                    emon.Port.cellsPush(sq, m);
                    cur = m;
                }
            }
            above = emon.Port.cellsLen(sq);
            if (above > 0) {
                int top = emon.Port.cellsAt(sq, above - 1);
                int tsize = inLsize(wd, lt, top);
                int d = captop - inCaptop(wd, lt, fo, et, top, tsize);
                int lb = inNext(lt, sc, l, s, cs - (body / IN_BACK_DIV), ce + (body * 2));
                if ((d * IN_CAP_TOP_DIV) > body) {
                    return 0;
                }
                if (((d + up) * IN_CAP_TOP_DIV) < (0 - body)) {
                    return 0;
                }
                if (lb >= 0) {
                    if ((inAbs(inStart(lt, lb, s) - cs) * IN_BACK_DIV) > inLsize(wd, lt, lb)) {
                        return 0;
                    }
                }
                if (inTaken(ii, top)) {
                    return 0;
                }
                emon.Port.cellsSet(lt, (l * 16) + Evidence.lhY0(), y0);
                emon.Port.cellsSet(lt, (l * 16) + Evidence.lhY1(), y1);
                emon.Port.cellsSet(lt, (l * 16) + Evidence.lhBy0(), lineBase);
                emon.Port.cellsSet(lt, (l * 16) + 15, 0 - r);
                inApply(lt, sq, Model.ifmDrop(), above, l, s);
                inRecord(ii, Model.ifmDrop(), above + 1, l, top, r, ix0, iy0, ix1, iy1, w0);
                return 1;
            }
            int l2 = inNext(lt, sc, l, s, cs - (body * 2), cs + (body * 2));
            if (l2 < 0) {
                return 0;
            }
            if ((inAbs(inStart(lt, l2, s) - cs) * IN_BACK_DIV) > inLsize(wd, lt, l2)) {
                return 0;
            }
            emon.Port.cellsSet(lt, (l * 16) + Evidence.lhY0(), y0);
            emon.Port.cellsSet(lt, (l * 16) + Evidence.lhY1(), y1);
            emon.Port.cellsSet(lt, (l * 16) + Evidence.lhBy0(), lineBase);
            inRecord(ii, Model.ifmRaised(), 0, -1, l, r, ix0, iy0, ix1, iy1, w0);
            return 1;
        } else {
            if (((ibase - lineBase) * IN_SLACK_DIV) < body) {
                return 0;
            }
            int d = captop - (lineBase - ((body * ratio) / 1000));
            if ((d * IN_CAP_TOP_DIV) > body) {
                return 0;
            }
            if (((d + up) * IN_CAP_TOP_DIV) < (0 - body)) {
                return 0;
            }
            emon.Port.cellsDrop(sq, 0);
            cur = l;
            while ((more == 1) && (emon.Port.cellsLen(sq) < IN_MAXLINES)) {
                m = inNext(lt, sc, cur, s, cs - (body / IN_BACK_DIV), ce + (body * 2));
                if (m < 0) {
                    more = 0;
                } else if ((inAbs(inLsize(wd, lt, m) - body) * 10) > (body * 2)) {
                    more = 0;
                } else {
                    emon.Port.cellsPush(sq, m);
                    cur = m;
                }
            }
            p = 0;
            while ((p < emon.Port.cellsLen(sq)) && (((inStart(lt, emon.Port.cellsAt(sq, p), s) - ce) * IN_SLACK_DIV) >= (0 - body))) {
                p += 1;
            }
            ng = 0;
            k = 0;
            while ((ng == 0) && (k < emon.Port.cellsLen(sq))) {
                if (((ibase - inGet(lt, emon.Port.cellsAt(sq, k), Evidence.lhY1())) * IN_SLACK_DIV) <= body) {
                    ng = k + 1;
                }
                k += 1;
            }
            if (ng < 1) {
                return 0;
            }
            if (p != ng) {
                return 0;
            }
            if (p < emon.Port.cellsLen(sq)) {
                if ((inAbs(inStart(lt, emon.Port.cellsAt(sq, p), s) - cs) * IN_BACK_DIV) > body) {
                    return 0;
                }
            }
            emon.Port.cellsSet(lt, (l * 16) + Evidence.lhY0(), y0);
            emon.Port.cellsSet(lt, (l * 16) + Evidence.lhY1(), y1);
            emon.Port.cellsSet(lt, (l * 16) + Evidence.lhBy0(), lineBase);
            inApply(lt, sq, Model.ifmDrop(), p, l, s);
            inRecord(ii, Model.ifmDrop(), p + 1, -1, l, r, ix0, iy0, ix1, iy1, w0);
            return 1;
        }
    }
    public static int inPage(emon.Port.Cells wd, emon.Port.Cells gl, emon.Port.Cells fo, emon.Port.Cells et, emon.Port.Cells lt, int page, emon.Port.Cells sc, emon.Port.Cells sq, emon.Port.Cells tm, emon.Port.Cells ii) {
        // One page: its drop and margin initials, then its raised ones.
        int med = 0;
        int i = 0;
        int s = 0;
        int n = 0;
        int got = 0;
        int c = 0;
        int r0 = 0;
        inCollect(wd, lt, page, sc, tm);
        n = emon.Port.cellsLen(sc);
        if (n == 0) {
            return 0;
        }
        med = inMedian(tm);
        if (med < 1) {
            return 0;
        }
        i = 0;
        while (i < n) {
            c = emon.Port.cellsAt(sc, i);
            if ((Evidence.lnGet(lt, c, Evidence.lhCount()) == 1) && ((inLsize(wd, lt, c) * 10) >= (IN_MIN_PAGE * med)) && inWordOk(wd, et, Evidence.lnGet(lt, c, Evidence.lhFirst()))) {
                s = 0;
                got = 0;
                while ((s < 2) && (got == 0)) {
                    r0 = emon.Port.cellsLen(ii) / II_STRIDE;
                    got = inTryDrop(wd, lt, fo, et, sc, sq, ii, c, s);
                    if (got == 1) {
                        int rr = r0 * II_STRIDE;
                        inApply(lt, sq, emon.Port.cellsAt(ii, rr + II_FORM), emon.Port.cellsAt(ii, rr + II_LINES), c, s);
                        emon.Port.cellsSet(lt, (c * 16) + Evidence.lhPage(), 0);
                    }
                    s += 1;
                }
            }
            i += 1;
        }
        inCollect(wd, lt, page, sc, tm);
        n = emon.Port.cellsLen(sc);
        i = 0;
        while (i < n) {
            c = emon.Port.cellsAt(sc, i);
            if (!inTaken(ii, c) && ((Evidence.lnGet(lt, c, 15) == 0) && (Evidence.lnGet(lt, c, Evidence.lhCount()) > 1))) {
                s = inDirv(lt, c);
                inTryInline(wd, gl, lt, fo, et, sc, sq, ii, c, s);
            }
            i += 1;
        }
        return 0;
    }
